Golden Trace Test Pattern
Golden trace tests verify command sequences produce expected DataManager states:
TEST_CASE("golden trace: CopyByTimeRange copies line entities") {
    auto dm = std::make_shared&lt;DataManager&gt;();
    // ... set up data ...

    auto const json = R"({
        "commands": [{
            "command_name": "CopyByTimeRange",
            "parameters": {
                "source_key": "src", "destination_key": "dst",
                "start_frame": 0, "end_frame": 100
            }
        }]
    })";

    auto seq = rfl::json::read&lt;CommandSequenceDescriptor&gt;(json).value();
    CommandContext ctx;
    ctx.data_manager = dm;
    auto result = executeSequence(seq, ctx);
    REQUIRE(result.result.success);

    auto snap = snapshotDataManager(*dm);
    CHECK(snap.key_entity_count.at("dst") == expected_count);
}
This pattern enables TDD for widget command coverage: capture a trace, replay it as a regression test, and verify the final state with snapshot comparison.

CommandInfo
CommandInfo is a plain struct that holds static metadata for one registered command:
struct CommandInfo {
    std::string name;                              // "MoveByTimeRange"
    std::string description;                       // Human-readable description
    std::string category;                          // "data_mutation", "meta", etc.
    bool supports_undo = false;                    // Whether the command supports undo
    std::vector&lt;std::string&gt; supported_data_types; // e.g. {"LineData", "PointData"}
    ParameterSchema parameter_schema;              // Full field-level schema
};
Source: src/Commands/Core/CommandInfo.hpp

Factory Query Functions
Two functions in CommandFactory.hpp provide access to command metadata:
/// Return metadata for all registered commands
std::vector&lt;CommandInfo&gt; getAvailableCommands();

/// Return metadata for a single command, or std::nullopt if unknown
std::optional&lt;CommandInfo&gt; getCommandInfo(std::string const & name);
These are implemented alongside createCommand() in CommandFactory.cpp. Adding a new command requires one if-branch for creation and one entry in getAvailableCommands() — both in the same file.

Usage Example
#include "Commands/Core/CommandFactory.hpp"

// List all commands for a picker UI
auto commands = commands::getAvailableCommands();
for (auto const & cmd : commands) {
    // cmd.name, cmd.description, cmd.category for display
    // cmd.parameter_schema.fields for generating form widgets
}

// Get schema for a specific command
auto info = commands::getCommandInfo("MoveByTimeRange");
if (info) {
    for (auto const & field : info-&gt;parameter_schema.fields) {
        // field.name, field.type_name, field.tooltip, etc.
    }
}

Current Implementation
The current multi-channel loader in binary_loaders.hpp (readBinaryFileMultiChannel) reads data one time slice at a time:
std::vector&lt;T&gt; time_slice_buffer(num_channels);
while (file.read(..., sizeof(T) * num_channels)) {
    for (size_t i = 0; i &lt; num_channels; ++i) {
        data[i][current_time_index] = time_slice_buffer[i];
    }
    current_time_index++;
}
For 32 channels of int16 data, this reads 64 bytes per syscall - an extremely inefficient pattern.

Recommended Fix
Replace the time-slice reading in readBinaryFileMultiChannel with a chunked approach:
template&lt;typename T&gt;
inline std::vector&lt;std::vector&lt;T&gt;&gt; readBinaryFileMultiChannel(BinaryAnalogOptions const & options) {
    // ... validation code ...

    // Pre-allocate output vectors
    std::vector&lt;std::vector&lt;T&gt;&gt; data(options.num_channels);
    for (auto& ch : data) {
        ch.resize(num_samples_per_channel);
    }

    // Read in chunks of 10,000 time samples (adjust based on cache size)
    constexpr size_t CHUNK_TIME_SAMPLES = 10000;
    std::vector&lt;T&gt; chunk_buffer(CHUNK_TIME_SAMPLES * options.num_channels);

    file.seekg(options.header_size_bytes);
    size_t time_offset = 0;

    while (time_offset &lt; num_samples_per_channel) {
        size_t chunk_size = std::min(CHUNK_TIME_SAMPLES, num_samples_per_channel - time_offset);
        size_t bytes_to_read = chunk_size * options.num_channels * sizeof(T);

        // Single large read
        file.read(reinterpret_cast&lt;char*&gt;(chunk_buffer.data()), bytes_to_read);

        // Distribute to channels (cache-friendly inner loop on time)
        for (size_t t = 0; t &lt; chunk_size; ++t) {
            for (size_t ch = 0; ch &lt; options.num_channels; ++ch) {
                data[ch][time_offset + t] = chunk_buffer[t * options.num_channels + ch];
            }
        }

        time_offset += chunk_size;
    }

    return data;
}

