Frame-Indexed Upsert Example
auto time_frame = std::make_shared&lt;TimeFrame&gt;();
time_frame-&gt;setTotalFrameCount(100);

auto tensor = std::make_shared&lt;TensorData&gt;();

// First batch: frames 1–3
std::vector&lt;std::pair&lt;int, std::vector&lt;float&gt;&gt;&gt; batch1 = {
    {1, {1.0f, 2.0f}},
    {2, {3.0f, 4.0f}},
    {3, {5.0f, 6.0f}},
};
tensor-&gt;upsertRows(batch1, time_frame);
// tensor has 3 rows: frames 1, 2, 3

// Second batch: frames 2–4 (frame 2–3 overwritten, frame 4 appended)
std::vector&lt;std::pair&lt;int, std::vector&lt;float&gt;&gt;&gt; batch2 = {
    {2, {30.0f, 40.0f}},
    {3, {50.0f, 60.0f}},
    {4, {70.0f, 80.0f}},
};
tensor-&gt;upsertRows(batch2, time_frame);
// tensor now has 4 rows: frame 1 preserved, frames 2–3 overwritten, frame 4 appended

