QString LinePlotOpenGLWidget::exportToSVG() {
    auto const & cpu_data = _line_store.cpuData();
    if (cpu_data.numLines() == 0) {
        return {};
    }

    // Extract per-line colors from BatchLineRenderer's color override state
    auto const per_line_colors = _line_renderer.getPerLineColors();

    // Convert LineBatchData → RenderablePolyLineBatch
    glm::vec4 default_color{1.0f, 1.0f, 1.0f, 1.0f};  // Or from line style state
    glm::vec4 selected_color{1.0f, 0.6f, 0.0f, 0.9f};
    auto poly_batch = CorePlotting::convertLineBatchToPolyLines(
        cpu_data, default_color, selected_color, per_line_colors);

    // Build temporary RenderableScene
    CorePlotting::RenderableScene scene;
    scene.poly_line_batches.push_back(std::move(poly_batch));
    scene.view_matrix = _view_matrix;
    scene.projection_matrix = _projection_matrix;

    PlottingSVG::SVGSceneRenderer renderer;
    renderer.setScene(scene);
    renderer.setCanvasSize(_widget_width, _widget_height);

    if (_state) {
        renderer.setBackgroundColor(_state-&gt;getBackgroundColor().toStdString());
    }

    return QString::fromStdString(renderer.render());
}
